Assume that Assumptions 1 and 2 hold.
Additionally,
suppose that the covariance matrix $\Gamma$ of $\mathbf{W}_{Y}$
is invertible.


(a) The probability density function of the random vector $\Theta_{Y}$
can be expressed as
\begin{align}
&p\left(\theta_{1:n};\Theta_{Y}\right)
=\int_{0}^{\infty}\hspace{-0.15cm}\int_{0}^{\infty}\hspace{-0.2cm}\cdots \hspace{-0.15cm}\int_{0}^{\infty}\left(\overset{n}{\underset{\ell=1}{\prod}}r_{\ell}\right)
\hspace{-0.1cm} p\left(\mathbf{w};\mathbf{W}_{Y}\right)dr_{1}dr_{2}\cdots dr_{n}
\end{align}
for $\theta_{1:n}=(\theta_{1},\theta_{2},\ldots,\theta_{n})\in [0,2\pi)^{n}$,
where $\mathbf{w}=[r_{1}e^{i\theta_{1}} \  r_{2}e^{i\theta_{2}} \ \cdots \ r_{n}e^{i\theta_{n}}]^{\top}$.


(b) In the case $n=1$,
for any $t\in \mathbb{R}$ and $s>0$, the probability density function of $\Theta_{Y}(t,s)$ has the representation
\begin{align}
&p(\theta;\Theta_{Y}(t,s))
=\frac{1}{2\pi }e^{-q}
+
\frac{\sqrt{q}}{2\sqrt{\pi}}
\cos(\theta-\theta_{f}) \textup{exp}\left\{\hspace{-0.05cm}-q\left[1-\cos^{2}(\theta-\theta_{f})\right]\hspace{-0.05cm}\right\}
\hspace{-0.1cm}B_{q}(\theta-\theta_{f}),
\end{align}
for $\theta\in [0,2\pi)$, where
$\theta_{f}=\arg(W_{f}(t,s))$,
 $q=q(t,s)$ is a measure of signal quality defined in (19),
\begin{equation}
B_{q}(u)=1+\textup{erf}\left(\sqrt{q}\cos(u)\right),\ u\in \mathbb{R},
\end{equation}
and
\begin{equation*}
\textup{erf}(z) = \frac{2}{\sqrt{\pi}}\int_{0}^{z}e^{-v^{2}}dv,\ z\in \mathbb{R}.
\end{equation*}

Assume that Assumptions 1 and 2 hold.
Additionally,
suppose that the covariance matrix $\Gamma$ of $\mathbf{W}_{Y}$
is invertible.


(a) In the null case, that is, $Y=\Phi$,
\begin{align*}
p\left(\theta_{1:n};\Theta_{\Phi}\right)
=
\frac{(n-1)!}{2\pi^{n}\textup{det}(\Gamma) }
\int_{S_{+}^{n-1}}
\left(\overset{n}{\underset{\ell=1}{\prod}}\omega_{\ell}\right)
\left(\omega^{\top}\mathbf{M}\omega\right)^{-n}d\omega
\end{align*}
for $\theta_{1:n}\in [0,2\pi)^n$, where
$S_{+}^{n-1}=
\{\omega=[\omega_{1},\ldots,\omega_{n}]^{\top}\in\mathbb{R}^{n}\mid \|\omega\|=1\ \textup{and}\ \omega_{\ell}\geq 0\ \textup{for}\ \ell=1,2,\ldots,n\}$,
$d\omega$ is the surface measure on $S_{+}^{n-1}$, and
\begin{align*}
\mathbf{M} = \textup{diag}\left(e^{-i\theta_1}, \dots, e^{-i\theta_n} \right)\Gamma^{-1} \textup{diag}\left(e^{i\theta_1}, \dots, e^{i\theta_n}\right).
\end{align*}




(b) In the null case with $n=1$, $\Theta_{\Phi}$ is uniformly distributed over $[0,2\pi)$. When $n=2$,
 $p\left(\theta_{1:2};\Theta_{\Phi}\right)$
depends only on the difference $\theta_{2}-\theta_{1}$ as follows
\begin{align}
&p\left(\theta_{1:2};\Theta_{\Phi}\right)
=\frac{1 }{4\pi^{2}}\frac{\textup{det}(\Gamma)}{D(\theta_{2}-\theta_{1})}
+\frac{1 }{4\pi^{2}}\frac{\textup{det}(\Gamma)C(\theta_{2}-\theta_{1})}
{D(\theta_{2}-\theta_{1})^{3/2}}
\Big[\frac{\pi}{2}+
\tan^{-1}\Big(\frac{C(\theta_{2}-\theta_{1})}
{\sqrt{D(\theta_{2}-\theta_{1})}}
\Big)\Big],
\end{align}
where
\begin{align*}
C(\varphi)=\Re(\Gamma_{12}e^{i\varphi}),\ \varphi\in \mathbb{R},
\end{align*}
and
\begin{align*}
D(\varphi)= \Gamma_{11}\Gamma_{22}-|C(\varphi)|^2.
\end{align*}

Assume that all the conditions in Proposition 5 hold and adopt its notation. Then, for any $\varepsilon\in (0,\pi/2)$,
\begin{align}
\mathbb{P}\left(d\left(\Theta_{Y}(t,s),\arg(W_{f}(t,s))\right)>\varepsilon\right)
\leq \frac{\varepsilon}{\pi }e^{-q}
+\frac{2\varepsilon \sqrt{q}}{\sqrt{\pi}}\cos(\varepsilon)\textup{exp}\left\{-q\left[1-\cos^{2}(\varepsilon)\right]\right\},
\end{align}
where $d(\cdot,\cdot)$ denotes the cosine distance, defined as
\begin{align*}
d\left(\Theta_{Y}(t,s),\arg(W_{f}(t,s))\right)
= 1-\left|\cos\big(\Theta_{Y}(t,s)-\arg(W_{f}(t,s))\big)\right|.
\end{align*}

Assume that Assumption 2 holds.
For any $t_{1},t_{2}\in \mathbb{R}$ and $s_{1},s_{2}>0$,
\begin{align}
&\textup{Cov}\left(|W_{Y}(t_{1},s_{1})|^2, |W_{Y}(t_{2},s_{2})|^2\right)
\\=&4\underset{\Box,\triangle \in \{\Re,\Im\}}{\sum} \Box(W_{f}(t_{1},s_{1}))\triangle(W_{f}(t_{2},s_{2}))
\sqrt{s_{1}s_{2}}\int_{\mathbb{R}}e^{i(t_{1}-t_{2})\lambda} \overline{\widehat{\Box(\psi)}}(s_{1}\lambda)\widehat{\triangle(\psi)}(s_{2}\lambda)F(d\lambda)
\\&+2s_{1}s_{2}\left[\int_{\mathbb{R}}e^{i(t_{1}-t_{2})\lambda} \overline{\widehat{\Box(\psi)}}(s_{1}u)
\widehat{\triangle(\psi)}(s_{2}u)F(du)\right]^{2},
\end{align}
where $F$ is the spectral measure of $C_{\Phi}$.

Assume that Assumptions 1 and 2 hold.
For any $t_{1},t_{2}\in \mathbb{R}$ and $s_{1},s_{2}>0$,
the covariance of the magnitudes $|W_{Y}(t_{1},s_{1})|$ and $|W_{Y}(t_{2},s_{2})|$ has the representation
\begin{align}
&\textup{Cov}\left(|W_{Y}(t_{1},s_{1})|,|W_{Y}(t_{2},s_{2})|\right)
\\=&\int_{\mathbb{C}}|w|p\left(w;W_{Y}(t_{1},s_{1})W_{Y}(t_{2},s_{2})\right)dw
-\overset{2}{\underset{\ell=1}{\prod}}\int_{\mathbb{C}}|w|p\left(w;W_{Y}(t_{\ell},s_{\ell}) \right)dw,
\end{align}
where
\begin{align}
&p\left(w;W_{Y}(t_{1},s_{1})W_{Y}(t_{2},s_{2})\right)
\\=&
\int_{0}^{\infty}\int_{0}^{2\pi} \frac{1}{\pi^{2}\textup{det}(\Gamma)r}
\textup{exp}\left(-\left(
\left[\begin{array}{cc}re^{i\theta}\\ wr^{-1}e^{-i\theta}\end{array}\right]-\left[\begin{array}{cc}W_{f}(t_{1},s_{1})\\ W_{f}(t_{2},s_{2})\end{array}\right]\right)^{*}\right.
\\&\left.\Gamma^{-1}
\left(\left[\begin{array}{cc}re^{i\theta}\\ wr^{-1}e^{-i\theta}\end{array}\right]-\left[\begin{array}{cc}W_{f}(t_{1},s_{1})\\ W_{f}(t_{2},s_{2})\end{array}\right]\right)\right)d\theta dr
\end{align}













and
\begin{align*}
p\left(w;W_{Y}(t_{\ell},s_{\ell}) \right) = \frac{1}{\pi\Gamma_{\ell\ell}}
\textup{exp}\left(-\frac{1}{\Gamma_{\ell\ell}}\left|w-W_{f}(t_{\ell},s_{\ell})\right|^{2}\right)
\end{align*}
for $\ell=1,2.$

Assume that Assumptions 1 and 2 hold.
For the null case, i.e.,  $Y=\Phi$,
\begin{align}
&\textup{Cov}\left(\left|W_{\Phi}(t_{1},s_{1})\right|,\left|W_{\Phi}(t_{2},s_{2})\right|\right)
\\=&\frac{\pi}{4}\sqrt{\Gamma_{11}\Gamma_{22}}
\left[\hspace{-0.1cm}\left(\hspace{-0.06cm}1-\frac{|\Gamma_{12}|^{2}}{\Gamma_{11}\Gamma_{22}}\hspace{-0.06cm}\right)^2
{}_2F_1\left(\hspace{-0.06cm}\frac{3}{2},\frac{3}{2};1;\frac{|\Gamma_{12}|^{2}}{\Gamma_{11}\Gamma_{22}}\hspace{-0.06cm}\right)-1\hspace{-0.05cm}\right],
\end{align}
where $\Gamma_{11},$ $\Gamma_{22}$, and $\Gamma_{12}$ are given in (6).
The correlation coefficient between
$|W_{\Phi}(t_{1},s_{1})|$ and $|W_{\Phi}(t_{2},s_{2})|$ is given by
\begin{align}
&\textup{Corr}\left(\left|W_{\Phi}(t_{1},s_{1})\right|,\left|W_{\Phi}(t_{2},s_{2})\right|\right)
\\=&\left(\hspace{-0.06cm}\frac{4}{\pi}-1\hspace{-0.06cm}\right)^{-1}
\hspace{-0.06cm}\left[\hspace{-0.06cm}\left(\hspace{-0.06cm}1-\frac{|\Gamma_{12}|^{2}}{\Gamma_{11}\Gamma_{22}}\hspace{-0.06cm}\right)^2
\hspace{-0.06cm}{}_2F_1\left(\frac{3}{2},\frac{3}{2};1;\frac{|\Gamma_{12}|^{2}}{\Gamma_{11}\Gamma_{22}}\right)-1\hspace{-0.06cm}\right].
\end{align}
When $|\Gamma_{12}|^{2}/(\Gamma_{11}\Gamma_{22})\rightarrow 0,$
\begin{align}
\textup{Corr}\left(\left|W_{\Phi}(t_{1},s_{1})\right|,\left|W_{\Phi}(t_{2},s_{2})\right|\right)
\sim \left(\frac{16}{\pi}-4\right)^{-1}\frac{|\Gamma_{12}|^{2}}{\Gamma_{11}\Gamma_{22}}.
\end{align}

Assume that Assumptions 1 and 2 hold.
For any $t_{1},t_{2}\in \mathbb{R}$ and $s_{1},s_{2}>0$, the covariance of the phases $\Theta_{\Phi}(t_{1},s_{1})$ and $\Theta_{\Phi}(t_{2},s_{2})$ is a function of $|\Gamma_{12}|/\sqrt{\Gamma_{11}\Gamma_{22}}$ and $\arg(\Gamma_{12})$. Moreover, when $|\Gamma_{12}|/\sqrt{\Gamma_{11}\Gamma_{22}}$ tends to zero,
\begin{align}
\textup{Cov}\left(\Theta_{\Phi}(t_{1},s_{1}),\Theta_{\Phi}(t_{2},s_{2})\right)\sim \frac{\pi}{2}\cos\big(\arg(\Gamma_{12})\big) \frac{|\Gamma_{12}|}{\sqrt{\Gamma_{11}\Gamma_{22}}},
\end{align}
where the notation $\sim$ means that
\begin{align}
\left(\frac{\pi}{2}\cos\big(\arg(\Gamma_{12})\big) \frac{|\Gamma_{12}|}{\sqrt{\Gamma_{11}\Gamma_{22}}}\right)^{-1}\textup{Cov}\left(\Theta_{\Phi}(t_{1},s_{1}),\Theta_{\Phi}(t_{2},s_{2})\right)
\end{align}
converges to one when $|\Gamma_{12}|/\sqrt{\Gamma_{11}\Gamma_{22}}\rightarrow 0.$

Assume that Assumptions 1 and 2 hold.
For any $t_{1},t_{2}\in \mathbb{R}$ and $s_{1},s_{2}>0$, we have
\begin{align}
\mathbb{E}\left[e^{i(\Theta_{\Phi}(t_{1},s_{1})-\Theta_{\Phi}(t_{2},s_{2}))}\right]
=&\frac{\pi}{4}e^{i\arg\left(\Gamma_{12}\right)}
\left(1-\frac{|\Gamma_{12}|^{2}}{\Gamma_{11}\Gamma_{22}}\right)
\\&\times\frac{|\Gamma_{12}|}{\sqrt{\Gamma_{11}\Gamma_{22}}}
{}_2F_1\left(\frac{3}{2},\frac{3}{2};2;\frac{|\Gamma_{12}|^{2}}{\Gamma_{11}\Gamma_{22}}\right)
\end{align}
and $\mathbb{E}\left[e^{i(\Theta_{\Phi}(t_{1},s_{1})+\Theta_{\Phi}(t_{2},s_{2}))}\right]=0$.
